struct posix_acl* xfs_acl_to_posix_acl(struct xfs_acl* aclp) {
    int i;
    struct posix_acl *posix_acl = NULL;
    struct posix_acl_entry *entry;
    int count = aclp->count;

    if (count < 0 || count > XFS_ACL_MAX_ENTRIES) {
        return ERR_PTR(-EINVAL);
    }

    posix_acl = kmalloc(sizeof(*posix_acl), GFP_KERNEL);
    if (!posix_acl) {
        return ERR_PTR(-ENOMEM);
    }

    posix_acl->count = count;
    posix_acl->a_entries = kcalloc(count, sizeof(*entry), GFP_KERNEL);
    if (!posix_acl->a_entries) {
        kfree(posix_acl);
        return ERR_PTR(-ENOMEM);
    }

    for (i = 0; i < count; i++) {
        struct xfs_acl_entry *xfs_entry = &aclp->entries[i];
        entry = &posix_acl->a_entries[i];

        switch (xfs_entry->tag) {
            case XFS_ACL_USER_OBJ:
                entry->e_tag = POSIX_ACL_USER_OBJ;
                break;
            case XFS_ACL_USER:
                entry->e_tag = POSIX_ACL_USER;
                entry->e_id = xfs_entry->id;
                break;
            case XFS_ACL_GROUP_OBJ:
                entry->e_tag = POSIX_ACL_GROUP_OBJ;
                break;
            case XFS_ACL_GROUP:
                entry->e_tag = POSIX_ACL_GROUP;
                entry->e_id = xfs_entry->id;
                break;
            case XFS_ACL_OTHER:
                entry->e_tag = POSIX_ACL_OTHER;
                break;
            case XFS_ACL_MASK:
                entry->e_tag = POSIX_ACL_MASK;
                break;
            default:
                entry->e_tag = POSIX_ACL_UNDEFINED;
                break;
        }

        entry->e_perm = xfs_entry->perm;
    }

    return posix_acl;
}
